-- PostgreSQL baseline (PG migration 1) = the FINAL state of SQLite migrations 1-17 (src/migrations.js), squashed.
-- Fresh databases only: src/pg/migrate.js refuses to apply it to a database that already has tables.
-- Parity with SQLite is enforced by test/pg/schema-parity.test.js (allow-list of intentional differences:
-- test-support/pg-parity.js). Porting rules used throughout:
--   * Column order is SQLite's final order (including columns that were appended by ALTER TABLE ADD COLUMN).
--   * INTEGER PRIMARY KEY AUTOINCREMENT -> integer GENERATED BY DEFAULT AS IDENTITY (explicit ids stay insertable for
--     the Slice 7 data copy, which must then advance each identity sequence past the copied ids).
--   * INTEGER -> integer (int4; ids and counters stay far below 2^31, and node-pg returns int4 as a JS number);
--     sessions.expires holds epoch MILLISECONDS -> bigint. REAL (8-byte in SQLite) -> double precision.
--   * TEXT -> text COLLATE "C": byte-order comparison and sorting, exactly like SQLite's default BINARY collation, so
--     TEXT timestamps/dates/times compare and CHECK exactly as before (D-46: they stay TEXT, same formats).
--   * COLLATE NOCASE columns (assets.tag, accounts.login_email, employees.work_email) -> text COLLATE "C" plus a UNIQUE
--     index on lower(column). Under "C", lower() folds ASCII letters only — the same rule as SQLite NOCASE.
--   * DEFAULT (datetime('now')) -> the same 'YYYY-MM-DD HH:MM:SS' UTC text, per statement like SQLite's 'now'.
--   * GLOB 'pattern' format CHECKs -> anchored regular expressions with the identical character classes.
--   * Foreign keys keep their actions: RESTRICT stays RESTRICT (history FKs), CASCADE stays CASCADE, an unspecified
--     action stays NO ACTION. No overlap/exclusion constraints (D-46: per-asset row locking, src/pg/transaction.js).

CREATE TABLE employees (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name text COLLATE "C" NOT NULL,
  work_email text COLLATE "C",
  department text COLLATE "C",
  title text COLLATE "C",
  phone text COLLATE "C",
  status text COLLATE "C" NOT NULL DEFAULT 'active' CHECK (status IN ('active','inactive')),
  created_at text COLLATE "C" NOT NULL DEFAULT to_char(statement_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  can_self_checkout integer NOT NULL DEFAULT 1 CHECK (can_self_checkout IN (0,1)),
  building text COLLATE "C"
);
CREATE UNIQUE INDEX idx_employees_work_email ON employees (lower(work_email)) WHERE work_email IS NOT NULL;

CREATE TABLE accounts (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  employee_id integer UNIQUE REFERENCES employees(id),
  login_email text COLLATE "C" NOT NULL,
  password_hash text COLLATE "C",
  role text COLLATE "C" NOT NULL DEFAULT 'employee' CHECK (role IN ('admin','employee')),
  active integer NOT NULL DEFAULT 1,
  created_at text COLLATE "C" NOT NULL DEFAULT to_char(statement_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  last_login_at text COLLATE "C"
);
CREATE UNIQUE INDEX accounts_login_email_lower_key ON accounts (lower(login_email));

CREATE TABLE catalog_nodes (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  parent_id integer REFERENCES catalog_nodes(id) ON DELETE RESTRICT,
  name text COLLATE "C" NOT NULL CHECK (length(trim(name)) > 0),
  name_key text COLLATE "C" NOT NULL CHECK (length(name_key) > 0),
  archived_at text COLLATE "C",
  created_at text COLLATE "C" NOT NULL DEFAULT to_char(statement_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  updated_at text COLLATE "C" NOT NULL DEFAULT to_char(statement_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  search_keywords text COLLATE "C",
  CHECK (parent_id IS NULL OR parent_id <> id)
);
CREATE UNIQUE INDEX idx_catalog_sibling_name ON catalog_nodes (COALESCE(parent_id, 0), name_key);
CREATE INDEX idx_catalog_parent ON catalog_nodes (parent_id);

CREATE TABLE assets (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tag text COLLATE "C" NOT NULL,
  name text COLLATE "C" NOT NULL,
  category text COLLATE "C" NOT NULL DEFAULT 'Other',
  brand text COLLATE "C",
  model text COLLATE "C",
  serial text COLLATE "C",
  status text COLLATE "C" NOT NULL DEFAULT 'available'
    CHECK (status IN ('available','checked_out','maintenance','retired','lost','disposed')),
  condition text COLLATE "C" DEFAULT 'Good',
  location text COLLATE "C",
  purchase_date text COLLATE "C",
  purchase_cost double precision,
  vendor text COLLATE "C",
  warranty_expires text COLLATE "C",
  license_key text COLLATE "C",
  license_seats integer,
  license_expires text COLLATE "C",
  notes text COLLATE "C",
  cover_photo_id integer,
  created_at text COLLATE "C" NOT NULL DEFAULT to_char(statement_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  updated_at text COLLATE "C" NOT NULL DEFAULT to_char(statement_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  archived_at text COLLATE "C",
  serial_normalized text COLLATE "C",
  catalog_node_id integer REFERENCES catalog_nodes(id) ON DELETE RESTRICT,
  available_to_request integer NOT NULL DEFAULT 0 CHECK (available_to_request IN (0, 1)),
  reservation_requires_approval integer NOT NULL DEFAULT 0 CHECK (reservation_requires_approval IN (0, 1))
);
CREATE UNIQUE INDEX assets_tag_lower_key ON assets (lower(tag));
CREATE INDEX idx_assets_serial ON assets (serial);
CREATE UNIQUE INDEX idx_assets_serial_normalized ON assets (serial_normalized);
CREATE INDEX idx_assets_catalog ON assets (catalog_node_id);

CREATE TABLE asset_tag_counter (
  id integer PRIMARY KEY CHECK (id = 1),
  last_number integer NOT NULL
);

CREATE TABLE assignments (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  asset_id integer NOT NULL REFERENCES assets(id) ON DELETE RESTRICT,
  employee_id integer NOT NULL REFERENCES employees(id) ON DELETE RESTRICT,
  assignment_type text COLLATE "C" NOT NULL DEFAULT 'permanent' CHECK (assignment_type IN ('permanent','checkout')),
  checked_out_at text COLLATE "C" NOT NULL DEFAULT to_char(statement_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  checked_out_by integer REFERENCES accounts(id),
  due_date text COLLATE "C",
  due_time text COLLATE "C",
  condition_out text COLLATE "C",
  notes text COLLATE "C",
  returned_at text COLLATE "C",
  returned_to integer REFERENCES accounts(id),
  condition_in text COLLATE "C",
  return_notes text COLLATE "C",
  last_overdue_notice text COLLATE "C",
  CHECK ((assignment_type = 'permanent' AND due_date IS NULL AND due_time IS NULL)
      OR (assignment_type = 'checkout' AND due_date IS NOT NULL))
);
CREATE INDEX idx_assign_open ON assignments (asset_id, returned_at);
CREATE INDEX idx_assign_employee ON assignments (employee_id, returned_at);
CREATE UNIQUE INDEX idx_assign_active_unique ON assignments (asset_id, employee_id) WHERE returned_at IS NULL;

CREATE TABLE photos (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  asset_id integer NOT NULL REFERENCES assets(id) ON DELETE CASCADE,
  filename text COLLATE "C" NOT NULL,
  thumb text COLLATE "C" NOT NULL,
  caption text COLLATE "C",
  uploaded_by integer REFERENCES accounts(id),
  created_at text COLLATE "C" NOT NULL DEFAULT to_char(statement_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')
);

CREATE TABLE requests (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  type text COLLATE "C" NOT NULL CHECK (type IN ('equipment','return','issue')),
  status text COLLATE "C" NOT NULL DEFAULT 'open'
    CHECK (status IN ('open','approved','denied','dropped_off','completed','cancelled')),
  user_id integer NOT NULL REFERENCES employees(id) ON DELETE RESTRICT,
  asset_id integer REFERENCES assets(id) ON DELETE RESTRICT,
  category text COLLATE "C",
  message text COLLATE "C",
  needed_by text COLLATE "C",
  created_by integer REFERENCES accounts(id) ON DELETE RESTRICT,
  created_at text COLLATE "C" NOT NULL DEFAULT to_char(statement_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  resolved_by integer REFERENCES accounts(id) ON DELETE RESTRICT,
  resolved_at text COLLATE "C",
  resolution_note text COLLATE "C",
  requested_assignment_type text COLLATE "C" CHECK (requested_assignment_type IN ('permanent','checkout')),
  catalog_node_id integer REFERENCES catalog_nodes(id) ON DELETE RESTRICT,
  catalog_path text COLLATE "C",
  asset_label text COLLATE "C",
  opened_at text COLLATE "C",
  CHECK ((type = 'equipment' AND status IN ('open','approved','denied','completed','cancelled'))
      OR (type = 'return' AND status IN ('open','dropped_off','completed','cancelled'))
      OR (type = 'issue' AND status IN ('open','completed','cancelled'))),
  CHECK ((status IN ('open','dropped_off') AND resolved_at IS NULL AND resolved_by IS NULL)
      OR (status IN ('approved','denied','completed','cancelled') AND resolved_at IS NOT NULL)),
  CHECK (resolved_at IS NULL OR resolved_at >= created_at),
  CHECK (requested_assignment_type IS NULL OR type = 'equipment'),
  CHECK (requested_assignment_type IS NULL OR requested_assignment_type <> 'permanent' OR asset_id IS NOT NULL),
  CHECK (type <> 'issue' OR asset_id IS NOT NULL)
);
CREATE INDEX idx_requests_asset ON requests (asset_id);
CREATE INDEX idx_requests_employee_status ON requests (user_id, status);
CREATE UNIQUE INDEX idx_requests_live_return ON requests (asset_id, user_id) WHERE type = 'return' AND status IN ('open','dropped_off');
CREATE INDEX idx_requests_catalog ON requests (catalog_node_id);

CREATE TABLE activity (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  asset_id integer REFERENCES assets(id) ON DELETE RESTRICT,
  actor_id integer REFERENCES accounts(id),
  subject_user_id integer REFERENCES employees(id),
  action text COLLATE "C" NOT NULL,
  details text COLLATE "C",
  created_at text COLLATE "C" NOT NULL DEFAULT to_char(statement_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')
);
CREATE INDEX idx_activity_asset ON activity (asset_id, created_at);

CREATE TABLE tokens (
  token text COLLATE "C" PRIMARY KEY,
  user_id integer NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  purpose text COLLATE "C" NOT NULL,
  expires_at text COLLATE "C" NOT NULL
);

CREATE TABLE sessions (
  sid text COLLATE "C" PRIMARY KEY,
  sess text COLLATE "C" NOT NULL,
  expires bigint NOT NULL
);

CREATE TABLE outbox (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  to_addr text COLLATE "C" NOT NULL,
  subject text COLLATE "C" NOT NULL,
  body text COLLATE "C" NOT NULL,
  status text COLLATE "C" NOT NULL,
  error text COLLATE "C",
  created_at text COLLATE "C" NOT NULL DEFAULT to_char(statement_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  delivered_to text COLLATE "C"
);

CREATE TABLE settings (
  key text COLLATE "C" PRIMARY KEY,
  value text COLLATE "C"
);

CREATE TABLE waitlist_entries (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  asset_id integer NOT NULL REFERENCES assets(id) ON DELETE RESTRICT,
  employee_id integer NOT NULL REFERENCES employees(id) ON DELETE RESTRICT,
  start_date text COLLATE "C" NOT NULL CHECK (start_date ~ '^[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]$'),
  end_date text COLLATE "C" NOT NULL CHECK (end_date ~ '^[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]$'),
  status text COLLATE "C" NOT NULL DEFAULT 'waiting' CHECK (status IN ('waiting','held','fulfilled','declined','left','removed','expired')),
  created_by integer REFERENCES accounts(id) ON DELETE RESTRICT,
  created_at text COLLATE "C" NOT NULL DEFAULT to_char(statement_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  hold_started_at text COLLATE "C",
  hold_expires_at text COLLATE "C",
  hold_email_at text COLLATE "C",
  closed_at text COLLATE "C",
  closed_by integer REFERENCES accounts(id) ON DELETE RESTRICT,
  updated_at text COLLATE "C" NOT NULL DEFAULT to_char(statement_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  queue_seq integer NOT NULL DEFAULT 0,
  queued_at text COLLATE "C",
  start_time text COLLATE "C" CHECK (start_time IS NULL OR (start_time ~ '^[0-2][0-9]:[0-5][0-9]$' AND start_time < '24:00')),
  end_time text COLLATE "C" CHECK (end_time IS NULL OR (end_time ~ '^[0-2][0-9]:[0-5][0-9]$' AND end_time < '24:00')),
  request_group text COLLATE "C",
  CHECK (end_date >= start_date),
  CHECK (status <> 'held' OR (hold_started_at IS NOT NULL AND hold_expires_at IS NOT NULL)),
  CHECK (status IN ('waiting','held') OR closed_at IS NOT NULL)
);
CREATE INDEX idx_waitlist_asset ON waitlist_entries (asset_id, status, created_at);
CREATE INDEX idx_waitlist_employee ON waitlist_entries (employee_id, status);
CREATE INDEX idx_waitlist_queue ON waitlist_entries (asset_id, status, queue_seq);
CREATE INDEX idx_waitlist_entries_request_group ON waitlist_entries (request_group);

CREATE TABLE reservations (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  asset_id integer NOT NULL REFERENCES assets(id) ON DELETE RESTRICT,
  employee_id integer NOT NULL REFERENCES employees(id) ON DELETE RESTRICT,
  start_date text COLLATE "C" NOT NULL CHECK (start_date ~ '^[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]$'),
  end_date text COLLATE "C" NOT NULL CHECK (end_date ~ '^[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]$'),
  status text COLLATE "C" NOT NULL CHECK (status IN ('pending','confirmed','declined','cancelled')),
  requires_approval integer NOT NULL CHECK (requires_approval IN (0, 1)),
  created_by integer REFERENCES accounts(id) ON DELETE RESTRICT,
  created_at text COLLATE "C" NOT NULL DEFAULT to_char(statement_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  decided_by integer REFERENCES accounts(id) ON DELETE RESTRICT,
  decided_at text COLLATE "C",
  decision_note text COLLATE "C",
  cancelled_by integer REFERENCES accounts(id) ON DELETE RESTRICT,
  cancelled_at text COLLATE "C",
  updated_at text COLLATE "C" NOT NULL DEFAULT to_char(statement_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  waitlist_entry_id integer REFERENCES waitlist_entries(id) ON DELETE RESTRICT,
  start_time text COLLATE "C" CHECK (start_time IS NULL OR (start_time ~ '^[0-2][0-9]:[0-5][0-9]$' AND start_time < '24:00')),
  end_time text COLLATE "C" CHECK (end_time IS NULL OR (end_time ~ '^[0-2][0-9]:[0-5][0-9]$' AND end_time < '24:00')),
  request_group text COLLATE "C",
  CHECK (end_date >= start_date),
  CHECK (status <> 'pending' OR (requires_approval = 1 AND decided_at IS NULL)),
  CHECK (status <> 'declined' OR (requires_approval = 1 AND decided_at IS NOT NULL)),
  CHECK (status <> 'confirmed' OR requires_approval = 0 OR decided_at IS NOT NULL),
  CHECK (status <> 'cancelled' OR cancelled_at IS NOT NULL)
);
CREATE INDEX idx_reservations_asset ON reservations (asset_id, status, start_date);
CREATE INDEX idx_reservations_employee ON reservations (employee_id, status);
CREATE INDEX idx_reservations_request_group ON reservations (request_group);

-- Rows that SQLite migrations 4 and 11 write into a FRESH database (no assets, no settings yet), so a fresh
-- PostgreSQL database starts exactly like a fresh SQLite one: the tag counter at 0 and one root catalog node per
-- built-in default category, in order. The Slice 7 data copy replaces these rows with the copied ones.
INSERT INTO asset_tag_counter (id, last_number) VALUES (1, 0);
